def _sliced_with_maxsplit(seq, n, maxsplit=None):
    if maxsplit is None:
        return takewhile(len, (seq[i : i + n] for i in count(0, n)))

    def gen():
        nonlocal maxsplit
        for i in range(0, len(seq), n):
            slice_ = seq[i : i + n]
            if slice_:
                yield slice_
                maxsplit -= 1
                if maxsplit <= 0:
                    break
    return gen()

